ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns tem http://tempuri.org/
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns inv http://schemas.datacontract.org/2004/07/InventarioLTE
---
soapenv#Envelope @('xmlns:inv' : inv):{
    soapenv#Header:{},
    soapenv#Body:{
        tem#GestionarInventarioLTE:{
        	tem#composite:{
	        	'inv:Canal': payload.Canal,
	            'inv:Categoria': payload.Categoria,
	            'inv:ICCID': payload.ICCID,
	            'inv:IdPedido': payload.IdPedido,
	            'inv:IdServicio': payload.IdServicio,
	            'inv:MSISDN': payload.MSISDN,
	            'inv:NuevoIdent': payload.NuevoIdent,
	            'inv:Operacion': payload.Operacion,
	            'inv:Subcategoria': payload.Subcategoria,
	            'inv:Tramite': payload.Tramite
			}
        }
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var result = payload.Envelope.Body.GestionarInventarioLTEResponse.GestionarInventarioLTEResult
var errorDesc = ": " ++ payload..DescripcionError[0] default ""
---
if(result.DescripcionError == "Timeout") {
	"ResponseCode": "00",
	"ResponseDescription": "Timeout M6, Comuníquese con el área correspondiente"
}
else if (result.Resultado == "OK") {
	"ResponseCode": "01",
	"ResponseDescription": "FACTIBLE"
}
else {
	"ResponseCode": "00",
	"ResponseDescription": "NO FACTIBLE" ++ errorDesc
}
